class Solution {public String[]solve(int[][]moves,int[]targets){int n=targets.length;ArrayList<ArrayList<Integer>>reverse=new ArrayList<>();for(int i=0;i<n;i++)reverse.add(new ArrayList<>());int[]degree=new int[n],state=new int[n];for(int u=0;u<n;u++)if(targets[u]==0)for(int v=0;v<n;v++)if(moves[u][v]==1){degree[u]++;reverse.get(v).add(u);}ArrayList<Integer>q=new ArrayList<>();for(int u=0;u<n;u++)if(targets[u]==1||degree[u]==0){state[u]=2;q.add(u);}for(int i=0;i<q.size();i++){int v=q.get(i);for(int u:reverse.get(v))if(state[u]==0){if(state[v]==2){state[u]=1;q.add(u);}else if(--degree[u]==0){state[u]=2;q.add(u);}}}String[]out=new String[n];for(int i=0;i<n;i++)out[i]=state[i]==1?"WIN":state[i]==2?"LOSE":"DRAW";return out;}}